```javascript
// Declare necessary variables
let video;

p.setup = function() {
  // Create a canvas sized to globals width and height
  p.createCanvas(globals.width, globals.height);

  // Open the webcam and create a video capture. Audio is muted by default.
  video = globals.createCapture(p);
}

p.draw = function() {
  // Apply the global transformation matrix
  p.applyMatrix(globals.matrix);

  // Set the background to black
  p.background(0);

  // Display the video feed on the canvas as black and white
  video.loadPixels();
  for (let y = 0; y < video.height; y += 10) {
    for (let x = 0; x < video.width; x += 10) {
      let index = (y * video.width + x) * 4;
      let r = video.pixels[index + 0];
      let g = video.pixels[index + 1];
      let b = video.pixels[index + 2];

      // Calculate luminance for black and white effect
      let bw = 0.2126 * r + 0.7152 * g + 0.0722 * b;

      p.fill(bw);
      p.noStroke();
      p.rect(x, y, 10, 10);
    }
  }

  // Draw a red circle in the center of the canvas
  p.fill(255, 0, 0); // Red color
  p.noStroke();
  p.ellipse(globals.width / 2, globals.height / 2, 100, 100); // Circle with diameter 100
}
